/' jadx-core/src/main/java/jadx/core/dex/instructions/mods/TernaryInsn.java && sed -i '19s/@Nullable IfCondition/IfCondition/' jadx-core/src/main/java/jadx/core/dex/instructions/mods/TernaryInsn.java && sed -i '36,38c\	private TernaryInsn() {
		super(InsnType.TERNARY, 2);
		// Initialize with a dummy compare-based condition to satisfy @NonNull contract
		jadx.core.dex.instructions.IfNode ifNode = new jadx.core.dex.instructions.IfNode(
				jadx.core.dex.instructions.IfOp.EQ,
				-1,
				jadx.core.dex.instructions.args.LiteralArg.litFalse(),
				jadx.core.dex.instructions.args.LiteralArg.litFalse());
		this.condition = new jadx.core.dex.regions.conditions.IfCondition(new jadx.core.dex.regions.conditions.Compare(ifNode));
	}' jadx-core/src/main/java/jadx/core/dex/instructions/mods/TernaryInsn.java && ./gradlew jadx-core:compileJava -x test -q > new_build_output.log 2>&1 && (grep -n "NullAway: .*errors" new_build_output.log || tail -n 80 new_build_output.log)
